class Solution:
    def calcEquation(self,equations,values,queries):
        graph=defaultdict(list)
        for (a,b),value in zip(equations,values):graph[a].append((b,value));graph[b].append((a,1/value))
        def query(a,b):
            if a not in graph or b not in graph:return -1.0
            stack=[(a,1.0)];seen={a}
            while stack:
                node,value=stack.pop()
                if node==b:return value
                for neighbor,weight in graph[node]:
                    if neighbor not in seen:seen.add(neighbor);stack.append((neighbor,value*weight))
            return -1.0
        return [query(a,b) for a,b in queries]

